<x-capstone::dialog id="add-member" title="Tambah Anggota" description="Masukkan alamat email mahasiswa yang ingin Anda undang ke kelompok Anda."><form class="space-y-4 mt-4" @submit.prevent="addMember()"><label class="grid gap-2 text-sm font-medium">Email<input type="email" x-model="memberEmail" required placeholder="student@example.com" class="file:text-on-surface placeholder:text-on-surface/50 selection:bg-primary selection:text-on-primary border-outline h-9 w-full min-w-0 rounded-radius border bg-surface px-3 py-1 text-sm text-on-surface shadow-xs transition-[color,box-shadow] outline-none file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm focus-visible:border-primary focus-visible:ring-2 focus-visible:ring-primary/20"/></label><p class="text-sm text-destructive" role="alert" x-text="errors.root"></p><div class="flex justify-end gap-2"><x-btn style="outline" @click="close('add-member')">Batal</x-btn><x-btn type="submit" x-bind:disabled="saving">Tambah Anggota</x-btn></div></form></x-capstone::dialog>
<x-capstone::dialog id="group-confirm"><h2 class="text-lg font-semibold pr-6" x-text="confirmTitle"></h2><p class="text-sm text-muted-foreground mt-2" x-text="confirmMessage"></p><p class="text-sm text-destructive mt-3" role="alert" x-text="errors.root"></p><div class="mt-6 flex justify-end gap-2"><x-btn style="outline" @click="close('group-confirm')">Batal</x-btn><x-btn @click="confirmSave()" x-bind:disabled="saving">Konfirmasi</x-btn></div></x-capstone::dialog>
